    /// <param name="timestampNS">a pointer filled in with the frame's timestamp, or 0 on error. Can be NULL.</param>
    /// <returns>a new frame of video on success, NULL if none is currently available.</returns>
    public static Surface* AcquireCameraFrame(Camera camera, out ulong timestampNS)
    {
        timestampNS = default;
        fixed (ulong* timestampNSPtr = &timestampNS)
        {
            return AcquireCameraFrame(camera, timestampNSPtr);
        }
    }

    /// <summary>Release a frame of video acquired from a camera.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_ReleaseCameraFrame</c>.</para>
    /// <para>Let the back-end re-use the internal buffer for camera.</para>
    /// <para>
    /// This function _must_ be called only on surface objects returned by SDL_AcquireCameraFrame(). This function
    /// should be called as quickly as possible after acquisition, as SDL keeps a small FIFO queue of surfaces for video
    /// frames; if surfaces aren't released in a timely manner, SDL may drop upcoming video frames from the camera.
    /// </para>
    /// <para>
    /// If the app needs to keep the surface for a significant time, they should make a copy of it and release the
    /// original.
    /// </para>
    /// <para>
    /// The app should not use the surface again after calling this function; assume the surface is freed and the
    /// pointer is invalid.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_AcquireCameraFrame</c>.</para>
    /// </remarks>
    /// <param name="camera">opened camera device.</param>
    /// <param name="frame">the video frame surface to release.</param>
    [LibraryImport("jade_native", EntryPoint = "SDL_ReleaseCameraFrame")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial void ReleaseCameraFrame(Camera camera, Surface* frame);

    /// <summary>Use this function to shut down camera processing and close the camera device.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_CloseCamera</c>.</para>
    /// <para>
    /// Thread safety: It is safe to call this function from any thread, but no thread may reference <c>device</c> once
    /// this function is called.
    /// </para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_OpenCamera</c>.</para>
    /// </remarks>
    /// <param name="camera">opened camera device.</param>
    [LibraryImport("jade_native", EntryPoint = "SDL_CloseCamera")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial void CloseCamera(Camera camera);
}
